# Writes crates/calc-doc/src/save/file_form_table.rs from the two Excel measurements beside this
# script (excel-prefixes.json, excel-array-positions.json):
#
#   python make-file-form-table.py
#
# Each row: a function's name, the prefix Excel writes before it, the argument count of the base
# call measured first, whether Excel stores the base call with each argument count from there as a
# dynamic array, and whether a range at each argument position makes it one. An entry Excel refused
# (null) is written as true: a dynamic array is the reading that changes no result.
import json
import os

here = os.path.dirname(os.path.abspath(__file__))
pre = json.load(open(os.path.join(here, 'excel-prefixes.json'), encoding='utf-8-sig'))
pos = json.load(open(os.path.join(here, 'excel-array-positions.json'), encoding='utf-8-sig'))
posmap = {r[0]: r for r in pos['rows']}
rows = []
for name, entered, stored in pre['rows']:
    if stored is None:
        continue
    if stored.startswith('_xlfn._xlws.'):
        prefix = 'XlfnXlws'
    elif stored.startswith('_xlfn.'):
        prefix = 'Xlfn'
    else:
        prefix = 'Bare'
    if name in ('LET', 'LAMBDA'):
        rows.append((name, prefix, 0, [], []))
        continue
    r = posmap[name]
    bases = r[2] if isinstance(r[2], list) else [r[2]]
    flags = r[3] if isinstance(r[3], list) else [r[3]]
    bases = [True if b is None else b for b in bases]
    flags = [True if f is None else f for f in flags]
    rows.append((name, prefix, r[1], bases, flags))
rows.sort(key=lambda r: r[0].encode())


def flags_text(values):
    return '[' + ', '.join('true' if v else 'false' for v in values) + ']'


out = [
    '//! Generated by tests/fixtures/d1/make-file-form-table.py from excel-prefixes.json and',
    '//! excel-array-positions.json, which measure-prefixes.ps1 and measure-array-positions.ps1',
    '//! measured with Excel 16.0 build 20430; the test',
    '//! d1_file_form__table_matches_the_measurements compares every row with them.',
    '',
    'use super::{FunctionFileForm, Prefix};',
    '',
    f'pub(super) const FUNCTIONS: [FunctionFileForm; {len(rows)}] = [',
]
for name, prefix, first, bases, flags in rows:
    out.append(
        f'    FunctionFileForm {{ name: "{name}", prefix: Prefix::{prefix}, first_count: {first}, '
        f'bases: &{flags_text(bases)}, positions: &{flags_text(flags)} }},'
    )
out.append('];')
target = os.path.join(here, '..', '..', '..', 'src', 'save', 'file_form_table.rs')
with open(target, 'w', encoding='utf-8', newline='\n') as f:
    f.write('\n'.join(out) + '\n')
print(len(rows))
